package com.jackandpaws.service; import com.jackandpaws.exception.ApiException;import com.jackandpaws.model.*;import com.jackandpaws.repository.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class FavoriteService {final FavoriteRepository favorites;final PetRepository pets;final CurrentUserService current;public FavoriteService(FavoriteRepository f,PetRepository p,CurrentUserService c){favorites=f;pets=p;current=c;}public List<Pet> list(){return favorites.findByUserOrderByCreatedAtDesc(current.get()).stream().map(Favorite::getPet).toList();}@Transactional public void add(Long petId){User u=current.get();Pet p=pets.findById(petId).orElseThrow(()->new ApiException(404,"Pet not found"));if(favorites.findByUserAndPet(u,p).isEmpty()){Favorite f=new Favorite();f.setUser(u);f.setPet(p);favorites.save(f);}}@Transactional public void remove(Long petId){User u=current.get();Pet p=pets.findById(petId).orElseThrow(()->new ApiException(404,"Pet not found"));favorites.deleteByUserAndPet(u,p);}}
